import yaml
lock = yaml.safe_load(open("dvc.lock"))
target = "checkpoints/sft_cat_a/gemma-4-26B-A4B-it"
names = {"f89238076f5b09ca0d76e5b9ab98e4ec.dir": "v2", "d5438dced5a25f54af0d73e8569c6483.dir": "v3"}
for stage, body in (lock.get("stages") or {}).items():
    for kind in ("deps", "outs"):
        for item in body.get(kind) or []:
            if item.get("path", "").startswith(target):
                h = item.get("md5", "")
                print(f"{stage:34s} {kind:5s} {names.get(h,'?'):3s} {h[:20]}  {item.get('size',0)/1e6:7.1f} MB  {item['path']}")
EOF

